import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function idOf(req: Request): string {
  const id = req.params['mainBudgetId'];
  if (typeof id !== 'string' || !/^[0-9]+$/.test(id)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '본예산 ID 형식이 올바르지 않습니다.');
  }
  return id;
}

function optionalText(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return String(value);
}

function optionalInt(value: unknown, label: string): string | null {
  const text = optionalText(value);
  if (text === null) {
    return null;
  }
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값은 숫자여야 합니다.');
  }
  return text;
}

// 마감·마감취소·승인·승인취소 공통 처리: 허용된 현재 상태에서만 바꾸고 이력을 남긴다.
// change_history.change_type 허용값에 마감취소·승인취소가 없어 '수정'으로 기록한다 (가정).
async function moveStatus(
  mainBudgetId: string,
  userId: string,
  from: string,
  to: string,
  changeType: string,
  conflictMessage: string,
): Promise<{ status: string }> {
  return transaction(async (db) => {
    const rows = await db.query(
      `SELECT status FROM main_budget WHERE main_budget_id = CAST(:id AS bigint) FOR UPDATE`,
      { id: mainBudgetId },
    );
    if (rows.length === 0) {
      throw new ApiError(404, 'MAIN_BUDGET_NOT_FOUND', '대상 본예산을 찾을 수 없습니다.');
    }
    const before = String(rows[0]['status']);
    if (before !== from) {
      throw new ApiError(409, 'MAIN_BUDGET_STATUS_CONFLICT', conflictMessage + ' (현재 상태: ' + before + ')');
    }
    await db.execute(
      `UPDATE main_budget SET status = :to, updated_at = now() WHERE main_budget_id = CAST(:id AS bigint)`,
      { to, id: mainBudgetId },
    );
    await db.execute(
      `INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at)
       VALUES ('main_budget', CAST(:id AS bigint), :changeType, now(), CAST(:userId AS bigint), :beforeContent, :afterContent, now(), now())`,
      {
        id: mainBudgetId,
        changeType,
        userId,
        beforeContent: '상태: ' + before,
        afterContent: '상태: ' + to,
      },
    );
    return { status: to };
  });
}

@Controller('api/v1')
export class FnSfr00302Controller {
  @Get('/main-budgets')
  async listMainBudgets(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const query = checks.queryOf(req.query);
    const accountingUnit = optionalText(query['accountingUnit']);
    const fiscalYear = optionalInt(query['fiscalYear'], '기수(회계연도)');
    const projectId = optionalInt(query['projectId'], '프로젝트 ID');
    const budgetGroup = optionalText(query['budgetGroup']);
    const status = optionalText(query['status']);
    const pageText = optionalInt(query['page'], 'page');
    const sizeText = optionalInt(query['size'], 'size');
    const page = pageText === null ? 0 : Number(pageText);
    let size = sizeText === null ? DEFAULT_SIZE : Number(sizeText);
    if (size < 1) {
      size = DEFAULT_SIZE;
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const where = `FROM main_budget m
        JOIN budget_item b ON b.budget_item_id = m.budget_item_id
        WHERE (CAST(:accountingUnit AS varchar) IS NULL OR m.accounting_unit = CAST(:accountingUnit AS varchar))
          AND (CAST(:fiscalYear AS integer) IS NULL OR m.fiscal_year = CAST(:fiscalYear AS integer))
          AND (CAST(:projectId AS bigint) IS NULL OR m.project_id = CAST(:projectId AS bigint))
          AND (CAST(:budgetGroup AS varchar) IS NULL OR b.budget_group = CAST(:budgetGroup AS varchar))
          AND (CAST(:status AS varchar) IS NULL OR m.status = CAST(:status AS varchar))`;
      const filter = { accountingUnit, fiscalYear, projectId, budgetGroup, status };
      const items = await db.query(
        `SELECT m.main_budget_id AS "mainBudgetId",
                m.project_id AS "projectId",
                m.budget_item_id AS "budgetItemId",
                m.accounting_unit AS "accountingUnit",
                m.fiscal_year AS "fiscalYear",
                m.request_amount AS "requestAmount",
                m.status AS "status"
         ` + where + `
         ORDER BY m.main_budget_id DESC
         LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...filter, size: String(size), offset: String(page * size) },
      );
      const counted = await db.query(`SELECT COUNT(*) AS total ` + where, filter);
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }

  @Post('/main-budgets/:mainBudgetId/close')
  @HttpCode(200)
  async closeMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = idOf(req);
    return moveStatus(id, user.id, '신청', '마감', '마감', '신청 상태의 본예산만 마감할 수 있습니다.');
  }

  @Post('/main-budgets/:mainBudgetId/cancel-close')
  @HttpCode(200)
  async cancelCloseMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = idOf(req);
    return moveStatus(id, user.id, '마감', '마감취소', '수정', '마감 상태의 본예산만 마감취소할 수 있습니다.');
  }

  @Post('/main-budgets/:mainBudgetId/submit-approval')
  @HttpCode(200)
  async submitMainBudgetApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = idOf(req);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT status, approval_document_id AS "approvalDocumentId"
         FROM main_budget WHERE main_budget_id = CAST(:id AS bigint) FOR UPDATE`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'MAIN_BUDGET_NOT_FOUND', '대상 본예산을 찾을 수 없습니다.');
      }
      if (String(rows[0]['status']) !== '마감') {
        throw new ApiError(409, 'MAIN_BUDGET_NOT_CLOSED', '마감된 본예산만 전자결재로 상신할 수 있습니다. 먼저 마감하세요.');
      }
      const documentId = rows[0]['approvalDocumentId'];
      if (documentId === null || documentId === undefined) {
        // 가정: 전자결재 모듈(S2) 상신 연계는 공통 기능이 맡는다. 연결된 결재문서가 없으면 상신 실패로 보고 상태를 바꾸지 않는다.
        throw new ApiError(502, 'APPROVAL_SUBMIT_FAILED', '전자결재 연계에 실패했습니다. 결재문서가 연결되지 않았습니다.');
      }
      const docs = await db.query(
        `SELECT approval_status AS "approvalStatus" FROM approval_document WHERE approval_document_id = CAST(:docId AS bigint)`,
        { docId: String(documentId) },
      );
      if (docs.length === 0) {
        throw new ApiError(502, 'APPROVAL_SUBMIT_FAILED', '전자결재 연계에 실패했습니다. 결재문서를 찾을 수 없습니다.');
      }
      return {
        approvalDocumentId: Number(documentId),
        submitResult: String(docs[0]['approvalStatus']),
      };
    });
  }

  @Post('/main-budgets/:mainBudgetId/approve')
  @HttpCode(200)
  async approveMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = idOf(req);
    return moveStatus(id, user.id, '마감', '승인', '승인', '마감 상태의 본예산만 승인할 수 있습니다.');
  }

  @Post('/main-budgets/:mainBudgetId/cancel-approval')
  @HttpCode(200)
  async cancelApprovalMainBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = idOf(req);
    return moveStatus(id, user.id, '승인', '승인취소', '수정', '승인 상태의 본예산만 승인취소할 수 있습니다.');
  }
}

