import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감취소', '마감취소'],
  ['승인', '승인'],
  ['승인취소', '승인취소'],
];

export default function FnSfr00302Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/main-budgets', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );
  const requested = useData<Page>(
    () => call<Page>('GET', '/main-budgets', role, undefined, { status: '신청', page: 0, size: 1 }),
    [role],
  );
  const closed = useData<Page>(
    () => call<Page>('GET', '/main-budgets', role, undefined, { status: '마감', page: 0, size: 1 }),
    [role],
  );
  const approved = useData<Page>(
    () => call<Page>('GET', '/main-budgets', role, undefined, { status: '승인', page: 0, size: 1 }),
    [role],
  );

  function refresh() {
    list.reload();
    requested.reload();
    closed.reload();
    approved.reload();
  }

  function setField(key: string, value: unknown) {
    setDraft({ ...draft, [key]: value });
  }

  function search() {
    setPage(0);
    setApplied({ ...draft });
  }

  function reset() {
    setDraft({});
    setPage(0);
    setApplied({});
  }

  async function act(path: string, done: string) {
    if (!selected) {
      return;
    }
    const result = await call<Row>('POST', '/main-budgets/' + String(selected.mainBudgetId) + path, role, {});
    notify(done);
    if (path === '/submit-approval') {
      notify('전자결재 상신 결과: ' + String(result.submitResult));
    }
    setSelected(null);
    refresh();
  }

  const status = selected ? String(selected.status) : '';

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['마감 대기(신청)', <Num value={requested.data?.total ?? 0} />],
            ['승인 대기(마감)', <Num value={closed.data?.total ?? 0} />],
            ['승인 완료', <Num value={approved.data?.total ?? 0} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>본예산</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="회계단위">
            <TextInput value={draft.accountingUnit} onChange={(v) => setField('accountingUnit', v)} />
          </Field>
          <Field label="기수(회계연도)">
            <NumberInput value={draft.fiscalYear} onChange={(v) => setField('fiscalYear', v)} />
          </Field>
          <Field label="프로젝트 ID">
            <LookupSelect
              table="project"
              role={role}
              value={draft.projectId}
              onChange={(v) => setField('projectId', v)}
            />
          </Field>
          <Field label="예산그룹">
            <TextInput value={draft.budgetGroup} onChange={(v) => setField('budgetGroup', v)} />
          </Field>
          <Field label="상태">
            <Select value={draft.status} onChange={(v) => setField('status', v)} options={STATUS_OPTIONS} />
          </Field>
        </Filters>
        <Band total={list.data?.total} />
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={list.data?.items ?? []}
          onRowClick={(row) => setSelected(row)}
          empty="조회된 본예산이 없습니다."
          columns={[
            { key: 'mainBudgetId', label: '본예산 ID' },
            {
              key: 'projectId',
              label: '프로젝트 ID',
              render: (row) => <RefName table="project" role={role} value={row.projectId} />,
            },
            {
              key: 'budgetItemId',
              label: '예산과목 ID',
              render: (row) => <RefName table="budget_item" role={role} value={row.budgetItemId} />,
            },
            { key: 'accountingUnit', label: '회계단위' },
            { key: 'fiscalYear', label: '기수(회계연도)' },
            { key: 'requestAmount', label: '신청금액', render: (row) => <Num value={row.requestAmount} /> },
            { key: 'status', label: '상태', render: (row) => <Badge value={row.status} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      {selected ? (
        <Drawer title="본예산 처리" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['본예산 ID', String(selected.mainBudgetId)],
              ['프로젝트 ID', <RefName table="project" role={role} value={selected.projectId} />],
              ['예산과목 ID', <RefName table="budget_item" role={role} value={selected.budgetItemId} />],
              ['회계단위', String(selected.accountingUnit)],
              ['기수(회계연도)', String(selected.fiscalYear)],
              ['신청금액', <Num value={selected.requestAmount} />],
              ['상태', <Badge value={selected.status} />],
            ]}
          />
          {status === '신청' ? (
            <Form submit="마감" onSubmit={() => act('/close', '본예산을 마감했습니다.')} />
          ) : null}
          {status === '마감' ? (
            <>
              <Form
                submit="전자결재 상신"
                onSubmit={() => act('/submit-approval', '전자결재로 상신했습니다.')}
              />
              <Form submit="승인" onSubmit={() => act('/approve', '본예산을 승인했습니다.')} />
              <Form
                submit="마감취소"
                danger
                onSubmit={() => act('/cancel-close', '본예산 마감을 취소했습니다.')}
              />
            </>
          ) : null}
          {status === '승인' ? (
            <Form
              submit="승인취소"
              danger
              onSubmit={() => act('/cancel-approval', '본예산 승인을 취소했습니다.')}
            />
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
